#include <QApplication>
#include <QSettings>
#include <QSaveFile>
#include <QTemporaryDir>
#include <QTimer>
#include <QMessageBox>
#include <QFile>
#include <cstdio>
#include <sys/resource.h>
#include <signal.h>
int main(int argc,char**argv) {
 QTemporaryDir config,dir;qputenv("QT_QPA_PLATFORM","offscreen");qputenv("XDG_CONFIG_HOME",config.path().toUtf8());
 QApplication app(argc,argv);app.setOrganizationName("cecore-test");app.setApplicationName("save-repro");
 int errors=0;QTimer dismiss;dismiss.setInterval(5);QObject::connect(&dismiss,&QTimer::timeout,[&]{if(auto*b=qobject_cast<QMessageBox*>(QApplication::activeModalWidget())){++errors;b->accept();}});
 auto save=[&](QString path){QSaveFile f(path);f.setDirectWriteFallback(false);if(!f.open(QIODevice::WriteOnly))return false;QByteArray bytes(3000,'x');bool ok=f.write(bytes)==bytes.size() && f.commit();if(!ok){f.cancelWriting();QMessageBox::critical(nullptr,"Save Cheat Table","Write failure");return false;}QSettings s;s.setValue("recentTables",QStringList{path,s.value("recentTables").toStringList().join('|')});return true;};
 auto xml=dir.filePath("saved.ct"),json=dir.filePath("saved.json");save(xml);save(json);QSettings settings;if(argc>1)settings.sync();auto recent=settings.value("recentTables");
 rlimit previous{};getrlimit(RLIMIT_FSIZE,&previous);rlimit cap=previous;cap.rlim_cur=64;signal(SIGXFSZ,SIG_IGN);setrlimit(RLIMIT_FSIZE,&cap);dismiss.start();bool rejectedXml=!save(xml),rejectedJson=!save(json);dismiss.stop();setrlimit(RLIMIT_FSIZE,&previous);
 QFile x(xml),j(json);x.open(QIODevice::ReadOnly);j.open(QIODevice::ReadOnly);bool same=QSettings().value("recentTables")==recent;
 printf("QT_SAVE_REPRO sync=%d qt=%s rejectedXml=%d rejectedJson=%d errors=%d recentUnchanged=%d xmlSize=%lld jsonSize=%lld xmlUnchanged=%d jsonUnchanged=%d\n",argc>1,qVersion(),rejectedXml,rejectedJson,errors,same,(long long)x.size(),(long long)j.size(),x.readAll()==QByteArray(3000,'x'),j.readAll()==QByteArray(3000,'x'));return 0;
}

